head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gAllChk = false;
scwin.gEmpNo = js_emp_no;
scwin.gIsurCd;
scwin.questNo;
scwin.gPvd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        scwin.hideDebugCtrls();
        await scwin.setHeader();
        await scwin.initPage();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30325.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_srch_onclick
 * @description 「받는곳 찾기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_srch_onclick = async function() {
    try {
        const options = {
            id: "ULDSTF30310",
            title: "수신자 선택",
            type: "browserPopup",
            width: "894px",
            height: "550px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/bizspt/ULDSTF30310.gfm", options);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30325.img_srch_onclick" });
    }
};

/**
 * @method
 * @name grd_Receiver_OnDblClick
 * @description grd_Receiver 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Receiver_OnDblClick = function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.setContnId(row);
        if (colid === "COM_ABBRV") {
            $c.stf.fn_PopupCorpInfo();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30325.grd_Receiver_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_cancel_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_cancel_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30325.btn_cancel_onclick" });
    }
};

/**
 * @method
 * @name img_send_onclick
 * @description 「전송」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_send_onclick = async function() {
    try {
        await scwin.registerMail();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30325.img_send_onclick" });
    }
};

/**
 * @method
 * @name img_cancel_onclick
 * @description 「취소」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_cancel_onclick = async function() {
    try {
        await scwin.cancel();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30325.img_cancel_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        let msg = $c.stf.getMessageParam("MSG-A002", "전송");
        await $c.win.alert(msg);
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30325.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        let msg = $c.stf.getMessageParam("MSG-A001", "전송");
        await $c.win.alert(msg);
        // frame.Provider("../"). fn_Search();
        // frame.Provider("../"+gPvd).fn_Search();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30325.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_SelectedAll_onclick
 * @description 「전체선택」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SelectedAll_onclick = function() {
    try {
        scwin.selectAll();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30325.btn_SelectedAll_onclick" });
    }
};

/**
 * @method
 * @name dts_Master_OnLoadError
 * @description dts_Master 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Master_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Master);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30325.dts_Master_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_fileData_OnLoadError
 * @description dts_fileData 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_fileData_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_fileData);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30325.dts_fileData_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Receiver_OnLoadError
 * @description dts_Receiver 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Receiver_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Receiver);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30325.dts_Receiver_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Receiver_OnLoadCompleted
 * @description dts_Receiver 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Receiver_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30325.dts_Receiver_OnLoadCompleted" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setHeader
 * @description set Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_Master",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Master=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_Master.insertRow();
    const sbmOptions2 = {
        id : "sbm_dts_Receiver",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Receiver=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 파일: 가우스헤더 셋팅
    const sbmOptions3 = {
        id : "sbm_dts_fileData",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_fileData=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setData
 * @description set Data 처리
 * @returns {void}
 * @hidden N
 */
scwin.setData = function() {
    txb_EMP_NO.setValue(scwin.gEmpNo);
    txb_fromName.setValue(js_emp_nm);
    txb_fromEmail.setValue(js_email);
    txb_EMAIL.setValue(js_email);
};

/**
 * @method
 * @name initPage
 * @description init Page 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initPage = async function() {
    scwin.questNo = $c.stf.getQuery(frame.srcUrl, "QUEST_NO");
    scwin.gPvd = $c.stf.getQuery(frame.srcUrl, "frameID");
    // alert('[gPvd]'+gPvd);
    await scwin.setHeader();
    scwin.setData();
};

/**
 * @method
 * @name hideDebugCtrls
 * @description hide Debug Ctrls 처리
 * @returns {void}
 * @hidden N
 */
scwin.hideDebugCtrls = function() {
    panel_debug.hide();
};

/**
 * @method
 * @name registerMail
 * @description register Mail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerMail = async function() {
    // alert_parse(dts_Receiver.Text, ",");return;
    if (await scwin.checkForm()) {
        let msg = $c.stf.getMessageParam("MSG-A006", "전송");
        const res = window.confirm(msg);
        if (res) {
            const url = "/EmailMgt.do?method=registerEmail" + "&SCREN_ID=" + "ULDSTF30325.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            // alert(dts_MASTER.Text);
            trs_Save.Action = url;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInputMaster=dts_Master, I:pInputDetail=dts_Receiver, I:pFile=dts_fileData)";
            trs_Save.post();
        }
    }
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    let msg = "";
    if ($c.ut.email_chk(txb_fromEmail.getValue()) === false) {
        await $c.win.alert("잘못된 이메일 주소입니다.");
        txb_fromEmail.focus();
        return false;
    }
    if (txb_title.getValue() === "") {
        msg = $c.stf.getMessageParam("MSG-A005", "제목");
        await $c.win.alert(msg);
        txb_title.focus();
        return false;
    }
    if (txa_content.getValue() === "") {
        msg = $c.stf.getMessageParam("MSG-A005", "내용");
        await $c.win.alert(msg);
        txa_content.focus();
        return false;
    }
    if (txb_EMP_NO.getValue() === "") {
        await $c.win.alert("세션정보를 받지 못했읍니다.");
        txb_EMP_NO.focus();
        return false;
    }

    // dts_Receiver 에서 CHECK 된 걸 찾는다.
    let total = 0;
    for (let i = 0; i < dts_Receiver.getRowCount(); i++) {
        const chk = dts_Receiver.getCellData(i, "CHECK");
        if (chk === "T" || chk === "1") {
            total++;
        }
    }
    if (total === 0) {
        await $c.win.alert("선택된 수신자가 없습니다.");
        return false;
    }
    if (js_svrGubun === 'local' || js_svrGubun === 'dev' || js_svrGubun === 'test') {
        await $c.win.alert("◆ 주의 사항 ◆\n\n개발환경에서도 메일이 발송되므로 수신자 메일주소를 확인바랍니다.");
    }
    return true;
};

/**
 * @method
 * @name cancel
 * @description cancel 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cancel = async function() {
    await scwin.setHeader();
    scwin.setData();
};

/**
 * @method
 * @name selectAll
 * @description select All 처리
 * @returns {void}
 * @hidden N
 */
scwin.selectAll = function() {
    grd_Receiver.Redraw = false;
    if (scwin.gAllChk === false) {
        // 현재상태가 false이면 전체선택을 클릭릭한것

        scwin.gAllChk = true;
        dts_Receiver.setBroadcast(false);
        for (let i = 0; i < dts_Receiver.getRowCount(); i++) {
            dts_Receiver.setCellData(i + 1, "CHECK", "T");
        }
        dts_Receiver.setBroadcast(true, true);
        btn_SelectedAll.setValue("전체해제");
    } else {
        // 현재상태가  true이면 전체선택을 클릭한것
        scwin.gAllChk = false;
        dts_Receiver.setBroadcast(false);
        for (let i = 0; i < dts_Receiver.getRowCount(); i++) {
            dts_Receiver.setCellData(i + 1, "CHECK", "F");
        }
        dts_Receiver.setBroadcast(true, true);
        btn_SelectedAll.setValue("전체선택");
    }
    grd_Receiver.Redraw = true;
};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gIsurCd = dts_Receiver.getCellData(Number(obj), "ISUR_CD");
    // alert("부모창:"+ gIsurCd);

};

/**
 * @method
 * @name grd_Receiver_CanColumnPosChange
 * @description grd Receiver Can Column Pos Change 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Receiver_CanColumnPosChange = function(row, colid) {
    return true;
};
